import React, { startTransition } from 'react';
import { ISalesDetailsData } from '../../core/Interface/sale.interface';
import { formatDateTime, getPriceFormat } from '../../core/utils';
import { Box, Chip, Tooltip, Typography } from '@mui/material';
import VisibilityIcon from '@mui/icons-material/Visibility';
import WhatsAppIcon from '@mui/icons-material/WhatsApp';
import RotateLeftIcon from '@mui/icons-material/RotateLeft';
import FormatListBulletedIcon from '@mui/icons-material/FormatListBulleted';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';
import { Privileges } from '../../core/types/commonType';
import useUser from '../../core/hooks/useUser';
import { CellContext } from '@tanstack/react-table';

const ActionBtn = ({
  onClick,
  title,
  color,
  children,
  show = true,
}: {
  onClick: () => void;
  title: string;
  color: string;
  children: React.ReactNode;
  show?: boolean;
}) => {
  if (!show) return null;
  return (
    <Tooltip arrow title={title}>
      <Box
        onClick={(e) => { e.stopPropagation(); onClick(); }}
        sx={{
          alignItems: 'center',
          background: `${color}18`,
          borderRadius: '6px',
          color,
          cursor: 'pointer',
          display: 'flex',
          height: 28,
          justifyContent: 'center',
          width: 28,
          '&:hover': { background: `${color}30` },
        }}
      >
        {children}
      </Box>
    </Tooltip>
  );
};

const paymentChipColor: Record<string, { bg: string; color: string }> = {
  cash:   { bg: '#DCFCE7', color: '#16A34A' },
  card:   { bg: '#DBEAFE', color: '#1D4ED8' },
  credit: { bg: '#FEF3C7', color: '#D97706' },
  bank:   { bg: '#F3E8FF', color: '#7C3AED' },
};

const getPaymentStyle = (method: string) => {
  const key = method?.toLowerCase();
  return paymentChipColor[key] ?? { bg: '#F1F5F9', color: '#475569' };
};

const useSalesDetailsColumn = ({
  viewSaleDetails,
  viewSaleDetailsPopUp,
  currencyCode,
}: {
  viewSaleDetails?: (id: string) => void;
  viewSaleDetailsPopUp?: (id: string) => void;
  currencyCode: string;
}) => {
  const { userHasRight } = useUser();
  const { t } = useTranslation(['salesdetails']);
  const navigate = useNavigate();

  return [
    {
      accessorKey: 'sn',
      header: '#',
      size: 50,
      cell: (cell: CellContext<ISalesDetailsData, unknown>) => {
        const { row, table } = cell;
        const { pageIndex, pageSize } = table.getState().pagination;
        return (
          <Typography sx={{ color: '#94A3B8', fontSize: '0.8rem', fontWeight: 600 }}>
            {pageIndex * pageSize + row.index + 1}
          </Typography>
        );
      },
    },
    {
      accessorKey: 'invoiceId',
      header: t('salesdetails:invoiceId'),
      size: 130,
      cell: (cell: CellContext<ISalesDetailsData, unknown>) => (
        <Typography sx={{ color: '#0F1D4D', fontSize: '0.82rem', fontWeight: 700 }}>
          {cell.row.original.invoiceId}
        </Typography>
      ),
    },
    {
      accessorKey: 'customerName',
      header: t('salesdetails:customerName'),
      size: 200,
      cell: (cell: CellContext<ISalesDetailsData, unknown>) => (
        <Typography sx={{ color: '#1E293B', fontSize: '0.84rem', fontWeight: 500 }}>
          {cell.row.original.customerName || '—'}
        </Typography>
      ),
    },
    {
      accessorKey: 'paymentMethod',
      header: t('salesdetails:paymentMethod'),
      size: 150,
      cell: (cell: CellContext<ISalesDetailsData, unknown>) => {
        const method = cell.row.original.paymentMethod;
        const style = getPaymentStyle(method);
        return (
          <Chip
            label={method || '—'}
            size="small"
            sx={{
              background: style.bg,
              color: style.color,
              fontSize: '0.75rem',
              fontWeight: 700,
              height: 22,
              borderRadius: '5px',
            }}
          />
        );
      },
    },
    {
      accessorKey: 'subTotal',
      header: () => <Box sx={{ textAlign: 'right' }}>{t('salesdetails:subTotal')}</Box>,
      size: 140,
      cell: (cell: CellContext<ISalesDetailsData, unknown>) => (
        <Box sx={{ textAlign: 'right' }}>
          <Typography sx={{ color: '#475569', fontSize: '0.84rem', fontWeight: 500 }}>
            {getPriceFormat(cell.row.original.subTotal, currencyCode)}
          </Typography>
        </Box>
      ),
    },
    {
      accessorKey: 'total',
      header: () => <Box sx={{ textAlign: 'right' }}>{t('salesdetails:total')}</Box>,
      size: 140,
      cell: (cell: CellContext<ISalesDetailsData, unknown>) => (
        <Box sx={{ textAlign: 'right' }}>
          <Typography sx={{ color: '#0F1D4D', fontSize: '0.88rem', fontWeight: 700 }}>
            {getPriceFormat(cell.row.original.total, currencyCode)}
          </Typography>
        </Box>
      ),
    },
    {
      accessorKey: 'dateTime',
      header: () => <Box sx={{ textAlign: 'right' }}>{t('salesdetails:date')}</Box>,
      size: 200,
      cell: (cell: CellContext<ISalesDetailsData, unknown>) => (
        <Box sx={{ textAlign: 'right' }}>
          <Typography sx={{ color: '#64748B', fontSize: '0.8rem', fontWeight: 500 }}>
            {formatDateTime(new Date(cell.row.original.dateTime))}
          </Typography>
        </Box>
      ),
    },
    {
      id: 'actions',
      header: '',
      size: 130,
      cell: (cell: CellContext<ISalesDetailsData, unknown>) => {
        const data = cell.row.original;
        return (
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 0.75 }}>
            <ActionBtn color="#0F8B8D" onClick={() => viewSaleDetails?.(data.id)} title="Print Receipt">
              <VisibilityIcon sx={{ fontSize: 16 }} />
            </ActionBtn>

            <ActionBtn color="#2563EB" onClick={() => viewSaleDetailsPopUp?.(data.id)} title="View Details">
              <FormatListBulletedIcon sx={{ fontSize: 16 }} />
            </ActionBtn>

            {data.whatsAppShareLink && userHasRight(Privileges.Send_Whatsapp_Receipt) && (
              <ActionBtn color="#16A34A" onClick={() => window.open(data.whatsAppShareLink, '_blank')} title="WhatsApp">
                <WhatsAppIcon sx={{ fontSize: 16 }} />
              </ActionBtn>
            )}

            <ActionBtn
              color="#D97706"
              onClick={() => startTransition(() => navigate(`/sales-return/${data.id}`))}
              show={userHasRight(Privileges.SalesReturn)}
              title="Sales Return"
            >
              <RotateLeftIcon sx={{ fontSize: 16 }} />
            </ActionBtn>
          </Box>
        );
      },
    },
  ];
};

export default useSalesDetailsColumn;
