import {
  Backdrop,
  Box,
  Button,
  Chip,
  CircularProgress,
  InputAdornment,
  Paper,
  TextField,
  Typography,
} from '@mui/material';
import { Table } from '@tanstack/react-table';
import React, { useEffect, useMemo, useState } from 'react';
import { useReactToPrint } from 'react-to-print';
import PosTablePagination from '../../components/Table/PosTablePagination';
import ReactTable from '../../components/Table/ReactTable';
import { ISalesReceipt } from '../../core/Interface/sale.interface';
import usePageQuery from '../../core/hooks/usePageQuery';
import { Invoice } from './components/Invoice';
import { useGetSalesDetailsByOrderIdQuery, useGetUserQuery } from '../posApi';
import useSalesDetails from './useSalesDetails';
import AnimatedPage from '../../layouts/AnimatedPage';
import { calculateFontSize } from '../../core/utils';
import ViewReceipt from './components/ViewReceipt';
import { IUserInfo } from '../../core/Interface/user.interface';
import { useTranslation } from 'react-i18next';
import ReceiptLongIcon from '@mui/icons-material/ReceiptLong';
import SearchIcon from '@mui/icons-material/Search';
import { HEADER_GRADIENT } from '../../theme/appColors';

const SalesDetails = () => {
  const { t } = useTranslation(['common']);
  const {
    table,
    isLoading,
    totalCount,
    invoiceId,
    setSearchText,
    popUpOrderId,
    resetPagination,
  } = useSalesDetails();

  const {
    data: salesDetailsData,
    isLoading: salesDetailsLoading,
    isFetching,
  } = useGetSalesDetailsByOrderIdQuery(invoiceId.split('_')[0], {
    skip: !invoiceId,
  });

  const { setPage } = usePageQuery();
  const { data: companyData } = useGetUserQuery();
  const [openAddCategory, setOpenAddCategory] = useState(false);
  const [localSearch, setLocalSearch] = useState('');

  const printPaperSizeInPixel = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.branch.printPaperSizeInPixel) {
        return Number(userData.branch.printPaperSizeInPixel);
      }
    }
    return 10;
  }, [companyData]);

  const [salesDetails, setSalesDetails] = React.useState<ISalesReceipt>();

  useEffect(() => {
    if (popUpOrderId) setOpenAddCategory(true);
  }, [popUpOrderId]);

  const handlePaginationChangePage = (
    _event: React.MouseEvent<HTMLButtonElement> | null,
    newPage: number
  ) => {
    table.getState().pagination.pageIndex < newPage
      ? table.nextPage()
      : table.previousPage();
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event: React.ChangeEvent<HTMLInputElement>) => {
    table.setPageSize(parseInt(event.target.value, 10));
  };

  const handleSearch = (text: string) => {
    setSearchText(text);
    resetPagination();
  };

  useEffect(() => {
    if (
      !isLoading &&
      table.getState().pagination.pageIndex !== 0 &&
      table.getRowModel().rows.length === 0
    ) {
      setPage(0);
    }
  }, [isLoading, setPage, table]);

  useEffect(() => {
    setSalesDetails(salesDetailsData?.data as ISalesReceipt);
  }, [salesDetailsData, invoiceId]);

  const componentRef = React.useRef<HTMLDivElement | null>(null);
  const handlePrint = useReactToPrint({ content: () => componentRef.current });

  useEffect(() => {
    const timer = setTimeout(() => {
      if (salesDetails && componentRef.current) handlePrint();
    }, 10);
    return () => clearTimeout(timer);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [salesDetails, componentRef]);

  return (
    <AnimatedPage>
      <Box>
        {/* ── Page Header ─────────────────────────────────── */}
        <Paper
          elevation={0}
          sx={{
            background: HEADER_GRADIENT,
            borderRadius: 2,
            mb: 2,
            overflow: 'hidden',
          }}
        >
          <Box
            sx={{
              alignItems: 'center',
              display: 'flex',
              flexWrap: 'wrap',
              gap: 2,
              justifyContent: 'space-between',
              px: 3,
              py: 2,
            }}
          >
            {/* Title */}
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
              <Box
                sx={{
                  alignItems: 'center',
                  background: 'rgba(255,255,255,0.15)',
                  borderRadius: '10px',
                  display: 'flex',
                  height: 40,
                  justifyContent: 'center',
                  width: 40,
                }}
              >
                <ReceiptLongIcon sx={{ color: '#fff', fontSize: 22 }} />
              </Box>
              <Box>
                <Typography sx={{ color: '#fff', fontSize: 18, fontWeight: 800, lineHeight: 1.2 }}>
                  Sales List
                </Typography>
                <Typography sx={{ color: 'rgba(255,255,255,0.65)', fontSize: 12, fontWeight: 500 }}>
                  All transactions
                </Typography>
              </Box>
              {totalCount > 0 && (
                <Chip
                  label={`${totalCount} records`}
                  size="small"
                  sx={{
                    background: 'rgba(255,255,255,0.18)',
                    border: '1px solid rgba(255,255,255,0.3)',
                    color: '#fff',
                    fontWeight: 600,
                    fontSize: 11,
                  }}
                />
              )}
            </Box>

            {/* Search */}
            <Box sx={{ alignItems: 'center', display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
              <TextField
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon sx={{ color: 'rgba(255,255,255,0.7)', fontSize: 18 }} />
                    </InputAdornment>
                  ),
                }}
                onChange={(e) => setLocalSearch(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') handleSearch(localSearch);
                }}
                placeholder="Invoice ID or Customer Name…"
                size="small"
                sx={{
                  minWidth: { xs: '100%', sm: 220, md: 300 },
                  flex: { xs: 1, sm: 1, md: 'none' },
                  '& .MuiOutlinedInput-root': {
                    background: 'rgba(255,255,255,0.12)',
                    borderRadius: '8px',
                    color: '#fff',
                    height: 40,
                    '& fieldset': { borderColor: 'rgba(255,255,255,0.25)' },
                    '&:hover fieldset': { borderColor: 'rgba(255,255,255,0.5)' },
                    '&.Mui-focused fieldset': { borderColor: 'rgba(255,255,255,0.8)' },
                    '& input::placeholder': { color: 'rgba(255,255,255,0.55)', opacity: 1 },
                  },
                }}
                value={localSearch}
                variant="outlined"
              />
              <Button
                onClick={() => handleSearch(localSearch)}
                sx={{
                  background: 'rgba(255,255,255,0.15)',
                  border: '1px solid rgba(255,255,255,0.3)',
                  borderRadius: '8px',
                  color: '#fff',
                  flexShrink: 0,
                  fontWeight: 600,
                  height: 40,
                  px: 2.5,
                  '&:hover': { background: 'rgba(255,255,255,0.25)' },
                }}
                variant="contained"
              >
                Search
              </Button>
            </Box>
          </Box>
        </Paper>

        {/* ── Table ───────────────────────────────────────── */}
        <Paper
          elevation={0}
          sx={{
            border: '1px solid #E2E8F0',
            borderRadius: 2,
            overflow: 'hidden',
          }}
        >
          <Box sx={{ overflow: 'auto', maxWidth: '100%', minHeight: 480 }}>
            <ReactTable isLoading={isLoading} {...(table as Table<object>)} />
          </Box>

          {totalCount > 0 && (
            <PosTablePagination
              count={totalCount}
              data-testid="pos-pagination"
              onPageChange={handlePaginationChangePage}
              onRowsPerPageChange={handleChangeRowsPerPage}
              page={table.getState().pagination.pageIndex}
              rowsPerPage={table.getState().pagination.pageSize}
              rowsPerPageOptions={[5, 10, 20]}
            />
          )}
        </Paper>

        {/* hidden print area */}
        <div style={{ display: 'none' }}>
          {salesDetails && (
            <Invoice
              fontSize={calculateFontSize(printPaperSizeInPixel).fontSize}
              fontWeight={calculateFontSize(printPaperSizeInPixel).fontWeight}
              label={calculateFontSize(printPaperSizeInPixel).label}
              ref={componentRef}
              salesRes={salesDetails}
              width={printPaperSizeInPixel}
            />
          )}
        </div>

        {openAddCategory && (
          <ViewReceipt
            handleCloseDialog={() => setOpenAddCategory(false)}
            invoiceId={popUpOrderId}
            openModel={openAddCategory}
          />
        )}

        <Backdrop
          open={salesDetailsLoading || isFetching}
          sx={{ color: '#fff', zIndex: (theme) => theme.zIndex.drawer + 1 }}
        >
          <CircularProgress color="inherit" />
        </Backdrop>
      </Box>
    </AnimatedPage>
  );
};

export default SalesDetails;
