import React, { useEffect, useMemo, useState } from 'react';
import {
  Box,
  Button,
  Chip,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  Grid,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Tooltip,
  Typography,
  useMediaQuery,
} from '@mui/material';
import ReceiptLongIcon from '@mui/icons-material/ReceiptLong';
import PersonIcon from '@mui/icons-material/Person';
import CalendarTodayIcon from '@mui/icons-material/CalendarToday';
import BadgeIcon from '@mui/icons-material/Badge';
import { theme } from '../../../theme';
import { ISalesReceipt } from '../../../core/Interface/sale.interface';
import {
  formatDateTime,
  getPriceFormat,
  getPriceFormatWithoutCurrency,
} from '../../../core/utils';
import {
  useGetSalesDetailsByOrderIdQuery,
  useGetUserQuery,
} from '../../posApi';
import { IUserInfo } from '../../../core/Interface/user.interface';
import { HEADER_GRADIENT } from '../../../theme/appColors';

interface IViewReceipt {
  openModel: boolean;
  handleCloseDialog: () => void;
  invoiceId: string;
}

const InfoRow = ({
  icon,
  label,
  value,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
}) => (
  <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5, minWidth: 0 }}>
    <Box
      sx={{
        alignItems: 'center',
        background: 'rgba(15,29,77,0.08)',
        borderRadius: '8px',
        color: '#0F1D4D',
        display: 'flex',
        flexShrink: 0,
        height: 32,
        justifyContent: 'center',
        width: 32,
      }}
    >
      {icon}
    </Box>
    <Box sx={{ minWidth: 0 }}>
      <Typography sx={{ color: '#94A3B8', fontSize: '0.72rem', fontWeight: 600, letterSpacing: '0.04em', textTransform: 'uppercase' }}>
        {label}
      </Typography>
      <Typography sx={{ color: '#1E293B', fontSize: '0.88rem', fontWeight: 600 }} noWrap>
        {value || '—'}
      </Typography>
    </Box>
  </Box>
);

const SummaryRow = ({
  label,
  value,
  highlight = false,
  color,
  isDue = false,
}: {
  label: string;
  value: string;
  highlight?: boolean;
  color?: string;
  isDue?: boolean;
}) => (
  <Box
    sx={{
      alignItems: 'center',
      background: highlight ? 'linear-gradient(90deg, #0F1D4D08, #0F8B8D12)' : isDue ? '#FEF2F2' : 'transparent',
      border: highlight ? '1px solid #0F8B8D30' : 'none',
      borderRadius: highlight ? '8px' : 0,
      display: 'flex',
      justifyContent: 'space-between',
      px: highlight ? 2 : 1,
      py: highlight ? 1.25 : 0.75,
    }}
  >
    <Typography
      sx={{
        color: color ?? (highlight ? '#0F1D4D' : '#475569'),
        fontSize: highlight ? '0.97rem' : '0.88rem',
        fontWeight: highlight ? 800 : 500,
      }}
    >
      {label}
    </Typography>
    <Typography
      sx={{
        color: color ?? (highlight ? '#0F8B8D' : '#1E293B'),
        fontSize: highlight ? '1.05rem' : '0.88rem',
        fontWeight: highlight ? 800 : 600,
      }}
    >
      {value}
    </Typography>
  </Box>
);

const ViewReceipt = ({ openModel, handleCloseDialog, invoiceId }: IViewReceipt) => {
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [salesDetails, setSalesDetails] = useState<ISalesReceipt>();

  const { data, isLoading, isFetching } = useGetSalesDetailsByOrderIdQuery(
    invoiceId.split('_')[0],
    { skip: !invoiceId }
  );

  const { data: companyData } = useGetUserQuery();

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) return userData.company.currencyCode;
    }
    return '';
  }, [companyData]);

  useEffect(() => {
    if (data) setSalesDetails(data.data as ISalesReceipt);
  }, [data]);

  const receipt = useMemo(() => salesDetails, [salesDetails]);

  return (
    <Dialog
      aria-describedby="alert-dialog-description"
      fullScreen={isMobile}
      fullWidth={!isMobile}
      maxWidth="lg"
      onClose={handleCloseDialog}
      open={openModel}
      PaperProps={{ sx: { borderRadius: isMobile ? 0 : '12px', overflow: 'hidden' } }}
    >
      {/* ── Header ────────────────────────────────────── */}
      <DialogTitle sx={{ background: HEADER_GRADIENT, p: 0 }}>
        <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5, px: 3, py: 2 }}>
          <Box
            sx={{
              alignItems: 'center',
              background: 'rgba(255,255,255,0.15)',
              borderRadius: '10px',
              display: 'flex',
              height: 40,
              justifyContent: 'center',
              width: 40,
            }}
          >
            <ReceiptLongIcon sx={{ color: '#fff', fontSize: 22 }} />
          </Box>
          <Box>
            <Typography sx={{ color: '#fff', fontSize: 17, fontWeight: 800, lineHeight: 1.2 }}>
              Sales Details
            </Typography>
            <Typography sx={{ color: 'rgba(255,255,255,0.65)', fontSize: 11, fontWeight: 500 }}>
              Transaction breakdown
            </Typography>
          </Box>
        </Box>
      </DialogTitle>

      <DialogContent sx={{ p: 0 }}>
        {isLoading || isFetching ? (
          <Box sx={{ alignItems: 'center', display: 'flex', height: 240, justifyContent: 'center' }}>
            <CircularProgress sx={{ color: '#0F8B8D' }} />
          </Box>
        ) : receipt ? (
          <>
            {/* ── Info strip ────────────────────────────── */}
            <Box sx={{ background: '#F8FAFC', borderBottom: '1px solid #E2E8F0', px: 3, py: 2 }}>
              <Grid container spacing={2}>
                <Grid item xs={12} sm={6} md={3}>
                  <InfoRow
                    icon={<BadgeIcon sx={{ fontSize: 16 }} />}
                    label="Invoice ID"
                    value={receipt.invoiceId}
                  />
                </Grid>
                <Grid item xs={12} sm={6} md={3}>
                  <InfoRow
                    icon={<PersonIcon sx={{ fontSize: 16 }} />}
                    label="Sales By"
                    value={receipt.saleBy}
                  />
                </Grid>
                <Grid item xs={12} sm={6} md={3}>
                  <InfoRow
                    icon={<PersonIcon sx={{ fontSize: 16 }} />}
                    label="Customer"
                    value={receipt.customerName}
                  />
                </Grid>
                <Grid item xs={12} sm={6} md={3}>
                  <InfoRow
                    icon={<CalendarTodayIcon sx={{ fontSize: 16 }} />}
                    label="Date"
                    value={formatDateTime(new Date(receipt.dateTime))}
                  />
                </Grid>
              </Grid>
            </Box>

            {/* ── Items table ───────────────────────────── */}
            <Box sx={{ px: 3, pt: 2.5, pb: 1 }}>
              <Typography sx={{ color: '#0F1D4D', fontSize: '0.78rem', fontWeight: 700, letterSpacing: '0.06em', mb: 1, textTransform: 'uppercase' }}>
                Items
              </Typography>
              <TableContainer
                sx={{
                  border: '1px solid #E2E8F0',
                  borderRadius: '8px',
                  overflow: 'hidden',
                }}
              >
                <Table size="small">
                  <TableHead>
                    <TableRow sx={{ background: '#F1F5F9' }}>
                      {['Qty', 'Description', 'Unit Price', 'Discount/Item', 'Discount Value', 'Amount'].map((h, i) => (
                        <TableCell
                          key={h}
                          align={i === 0 ? 'left' : i >= 2 ? 'right' : 'left'}
                          sx={{
                            borderBottom: '2px solid #E2E8F0',
                            color: '#374151',
                            fontSize: '0.75rem',
                            fontWeight: 700,
                            letterSpacing: '0.03em',
                            py: 1.25,
                            whiteSpace: 'nowrap',
                          }}
                        >
                          {h === 'Discount/Item' ? (
                            <Tooltip arrow placement="top" title="Discount Per Item">
                              <span style={{ cursor: 'default', borderBottom: '1px dashed #94A3B8' }}>
                                {h}
                              </span>
                            </Tooltip>
                          ) : h}
                        </TableCell>
                      ))}
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {receipt.items?.map((item, index) => (
                      <TableRow
                        key={index}
                        sx={{
                          background: index % 2 === 0 ? '#fff' : '#F8FAFC',
                          '&:last-child td': { borderBottom: 'none' },
                        }}
                      >
                        <TableCell align="left" sx={{ color: '#334155', fontSize: '0.84rem', py: 1.25 }}>
                          <Chip
                            label={item.qty}
                            size="small"
                            sx={{ background: '#E0E7FF', color: '#3730A3', fontWeight: 700, fontSize: '0.75rem', height: 20, borderRadius: '4px' }}
                          />
                        </TableCell>
                        <TableCell sx={{ color: '#1E293B', fontSize: '0.84rem', fontWeight: 500, maxWidth: 200, py: 1.25, wordBreak: 'break-word' }}>
                          {item.productName}
                        </TableCell>
                        <TableCell align="right" sx={{ color: '#475569', fontSize: '0.84rem', py: 1.25 }}>
                          {getPriceFormat(item.unitPrice, currencyCode)}
                        </TableCell>
                        <TableCell align="right" sx={{ color: '#D97706', fontSize: '0.84rem', py: 1.25 }}>
                          {getPriceFormat(item.discount, currencyCode)}
                        </TableCell>
                        <TableCell align="right" sx={{ color: '#D97706', fontSize: '0.84rem', py: 1.25 }}>
                          {item.isDiscountPercentage
                            ? `${item.discountValue}%`
                            : getPriceFormat(item.discountValue, currencyCode)}
                        </TableCell>
                        <TableCell align="right" sx={{ color: '#0F1D4D', fontSize: '0.88rem', fontWeight: 700, py: 1.25 }}>
                          {getPriceFormat(item.amount, currencyCode)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            </Box>

            {/* ── Financial summary ─────────────────────── */}
            <Box sx={{ borderTop: '1px solid #E2E8F0', mt: 1, px: 3, py: 2 }}>
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, ml: 'auto', maxWidth: 360 }}>
                <SummaryRow
                  label="Sub Total"
                  value={getPriceFormat(receipt.subTotal, currencyCode)}
                />

                {receipt.discount > 0 && (
                  <SummaryRow
                    color="#D97706"
                    label={`Discount${receipt.isDiscountPercentage ? ` [${receipt.discountValue}%]` : ` [${getPriceFormatWithoutCurrency(receipt.discountValue)}]`}`}
                    value={`- ${getPriceFormat(receipt.totalDiscount, currencyCode)}`}
                  />
                )}

                <Divider sx={{ my: 0.5 }} />

                <SummaryRow
                  highlight
                  label="Net Total"
                  value={getPriceFormat(receipt.total)}
                />

                <SummaryRow
                  color="#16A34A"
                  label="Received"
                  value={getPriceFormat(receipt.received)}
                />

                {(receipt.return ?? 0) > 0 && (
                  <SummaryRow
                    color="#D97706"
                    label="Return"
                    value={getPriceFormat(receipt.return ?? 0)}
                  />
                )}

                <Divider sx={{ my: 0.5 }} />

                <SummaryRow
                  color={receipt.balance < 0 ? '#DC2626' : '#0F8B8D'}
                  isDue={receipt.balance < 0}
                  label={receipt.balance < 0 ? 'Due Amount' : 'Balance'}
                  value={getPriceFormat(Math.abs(receipt.balance))}
                />
              </Box>
            </Box>
          </>
        ) : (
          <Box sx={{ alignItems: 'center', display: 'flex', height: 200, justifyContent: 'center' }}>
            <Typography sx={{ color: '#94A3B8', fontSize: '0.9rem' }}>No data available</Typography>
          </Box>
        )}
      </DialogContent>

      {/* ── Footer ────────────────────────────────────── */}
      <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, p: 2, px: 3 }}>
        <Button
          onClick={handleCloseDialog}
          sx={{
            borderColor: '#CBD5E1',
            borderRadius: '8px',
            color: '#475569',
            fontWeight: 600,
            height: 40,
            px: 3,
            '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' },
          }}
          variant="outlined"
        >
          Close
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default React.memo(ViewReceipt);
