import {
  PaginationState,
  Row,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table';
import React, { CSSProperties, useMemo, useState } from 'react';
import {
  ISalesDetails,
  ISalesDetailsData,
} from '../../core/Interface/sale.interface';
import usePageQuery from '../../core/hooks/usePageQuery';
import { generateString } from '../../core/utils';
import { useGetAllSalesDetailsQuery, useGetUserQuery } from '../posApi';
import useSalesDetailsColumn from './useSalesDetailsColumn';
import { IUserInfo } from '../../core/Interface/user.interface';

const useSalesDetails = () => {
  const [invoiceId, setInvoiceId] = useState<string>('');
  const [popUpOrderId, setPopUpOrderId] = useState<string>('');
  const { page } = usePageQuery();
  const [pagination, setPagination] = React.useState<PaginationState>({
    pageIndex: page,
    pageSize: 10,
  });
  const [searchText, setSearchText] = useState('');

  const { data: companyData } = useGetUserQuery();

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) {
        return userData.company.currencyCode;
      }
    }
    return '';
  }, [companyData]);

  const {
    data: salesDetailsData,
    isLoading,
    isFetching,
    error,
  } = useGetAllSalesDetailsQuery({
    pageIndex: pagination.pageIndex,
    pageSize: pagination.pageSize,
    searchText,
  });

  const salesDetailsMemo = useMemo(() => {
    return salesDetailsData?.data as ISalesDetails;
  }, [salesDetailsData?.data]);

  const viewSaleDetails = (id: string) => {
    if (invoiceId === id) {
      setInvoiceId(id + '_' + generateString(5));
      setSearchText('');
    } else {
      setInvoiceId(id);
    }
  };

  const viewSaleDetailsPopUp = (id: string) => {
    if (popUpOrderId === id) {
      setPopUpOrderId(id + '_' + generateString(5));
    } else {
      setPopUpOrderId(id);
    }
  };

  // Server already filters and paginates — use records as-is.
  // Client-side re-filtering would cut into the already-paginated slice,
  // showing fewer rows per page than requested and corrupting page counts.
  const filteredData = useMemo(
    () => salesDetailsMemo?.records ?? [],
    [salesDetailsMemo?.records]
  );

  const columns = useSalesDetailsColumn({
    viewSaleDetails,
    viewSaleDetailsPopUp,
    currencyCode,
  });

  const table = useReactTable({
    data: error ? [] : filteredData,
    meta: {
      getRowStyles: (row: Row<ISalesDetailsData>): CSSProperties => ({}),
    },
    columns: columns,
    initialState: {
      columnVisibility: {
        id: false,
      },
    },
    // manualPagination expects the number of *pages*, not total records.
    pageCount: Math.ceil((salesDetailsMemo?.totalRecords ?? 0) / pagination.pageSize),
    state: {
      pagination,
    },
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
  });

  return {
    table,
    isLoading: isFetching || isLoading,
    isInitLoading: isLoading,
    error,
    totalCount: salesDetailsMemo?.totalRecords ?? 0,
    invoiceId,
    popUpOrderId,
    searchText,
    setSearchText,
    filteredData,
    setPopUpOrderId,
    resetPagination: () => setPagination({ ...pagination, pageIndex: 0 }),
  };
};

export default useSalesDetails;
